mapper.sql:
WHERE m.delete_yn = 'N'

  AND m.site_id = #{search.siteId}


  AND m.bbs_type = #{search.bbsType}


  AND m.use_yn = #{search.useYn}


  AND (m.bbs_name LIKE CONCAT('%', #{search.keyword}, '%')
    OR m.bbs_code LIKE CONCAT('%', #{search.keyword}, '%'))

mapper.select:
SELECT 
  FROM tb_bbs_master m
  JOIN tb_site s ON s.site_id = m.site_id
 WHERE s.site_code = #{siteCode}
   AND m.bbs_code  = #{bbsCode}
   AND m.delete_yn = 'N'


SELECT COUNT(1)
  FROM tb_bbs_master
 WHERE site_id   = #{siteId}
   AND bbs_code  = #{bbsCode}
   AND delete_yn = 'N'


  AND bbs_master_id <> #{excludeId}

mapper.delete:
DELETE FROM tb_bbs_master
 WHERE delete_yn = 'Y'
   AND updated_at <= #{cutoff}

mapper.select:
SELECT COUNT(*) FROM tb_bbs_master
 WHERE delete_yn = 'Y'
   AND updated_at <= #{cutoff}
